// ── Component Interface (base class in JS) ────────────────────────
class FileSystemItem {
  getName()           { throw new Error('getName() not implemented'); }
  getSize()           { throw new Error('getSize() not implemented'); }
  print(indent = '')  { throw new Error('print() not implemented'); }
}

// ── Leaf: concrete scalar implementation, no children ─────────────
class File extends FileSystemItem {
  constructor(name, sizeKB) {
    super();
    this._name = name;
    this._size = sizeKB;
  }
  getName()           { return this._name; }
  getSize()           { return this._size; }  // scalar — no delegation
  print(indent = '')  {
    console.log(`${indent}| ${this._name} (${this._size} KB)`);
  }
}

// ── Composite: stores children, delegates operations ──────────────
class Folder extends FileSystemItem {
  constructor(name) {
    super();
    this._name     = name;
    this._children = [];
  }

  // Builder-style fluent API — returns `this` for chaining
  add(item) {
    this._children.push(item);
    return this;
  }
  remove(item) {
    this._children = this._children.filter(c => c !== item);
  }

  getName() { return this._name; }

  // The composite magic: sum children's sizes recursively
  getSize() {
    return this._children.reduce((sum, child) => sum + child.getSize(), 0);
  }

  print(indent = '') {
    const size = this.getSize();
    console.log(`${indent}+ ${this._name}/ (${size} KB)`);
    this._children.forEach(child => child.print(indent + '  '));
  }
}

// ── Build an arbitrary tree ───────────────────────────────────────
const root = new Folder('root')
  .add(
    new Folder('docs')
      .add(new File('guide.pdf', 150))
      .add(new File('notes.txt', 5))
  )
  .add(
    new Folder('src')
      .add(new File('index.js', 12))
      .add(new File('utils.js', 8))
  )
  .add(new File('README.md', 2));

// ── Client: zero instanceof checks ───────────────────────────────
root.print();
// + root/ (177 KB)
//   + docs/ (155 KB)
//     | guide.pdf (150 KB)
//     | notes.txt (5 KB)
//   + src/ (20 KB)
//     | index.js (12 KB)
//     | utils.js (8 KB)
//   | README.md (2 KB)

console.log('Total:', root.getSize(), 'KB'); // Total: 177 KB

// ── Adding a new node type: zero changes to existing code ─────────
class Archive extends FileSystemItem {
  constructor(name, entries) {
    super();
    this._name    = name;
    this._entries = entries; // already-compressed, know total
  }
  getName()          { return this._name; }
  getSize()          { return this._entries.reduce((s, e) => s + e.size, 0); }
  print(indent = '') {
    console.log(`${indent}[zip] ${this._name} (${this.getSize()} KB)`);
  }
}

// Drop an Archive anywhere in the tree — existing Folder code is unchanged
const backup = new Folder('backup')
  .add(new Archive('photos.zip', [{size: 200}, {size: 300}]))
  .add(new File('manifest.txt', 1));

root.add(backup);
console.log('After archive:', root.getSize(), 'KB'); // 178 + 501 = 679 KB

// ── TypeScript: Safe Composite with explicit interface ────────────

// Component interface — shared by all nodes
interface UIComponent {
  render(): string;
  getRenderTime(): number;
  getName(): string;
}

// Leaf — a concrete widget with no children
class Button implements UIComponent {
  constructor(
    private readonly label: string,
    private readonly renderMs: number
  ) {}

  getName(): string        { return `Button[${this.label}]`; }
  getRenderTime(): number  { return this.renderMs; }
  render(): string         { return `<button>${this.label}</button>`; }
}

// Leaf — an icon
class Icon implements UIComponent {
  constructor(private readonly src: string) {}
  getName(): string        { return `Icon[${this.src}]`; }
  getRenderTime(): number  { return 1; }
  render(): string         { return `<img src="${this.src}" />`; }
}

// Composite — a panel that can contain any UIComponents
class Panel implements UIComponent {
  private children: UIComponent[] = [];

  constructor(private readonly name: string) {}

  // add/remove only on Composite — type-safe, not on UIComponent interface
  add(child: UIComponent): Panel {
    this.children.push(child);
    return this;  // fluent
  }
  remove(child: UIComponent): void {
    this.children = this.children.filter(c => c !== child);
  }

  getName(): string {
    return `Panel[${this.name}]`;
  }
  // Delegation: sum all children
  getRenderTime(): number {
    return this.children.reduce((sum, c) => sum + c.getRenderTime(), 0);
  }
  render(): string {
    const inner = this.children.map(c => c.render()).join('\n');
    return `<div class="panel" id="${this.name}">\n${inner}\n</div>`;
  }
}

// ── Build the UI tree ─────────────────────────────────────────────
const sidebar = new Panel('sidebar')
  .add(new Icon('menu.svg'))
  .add(new Button('Profile', 2))
  .add(new Button('Settings', 2));

const app = new Panel('app')
  .add(sidebar)
  .add(new Panel('content')
    .add(new Button('Submit', 3))
    .add(new Button('Cancel', 2)))
  .add(new Button('Logout', 1));

// ── Client: only sees UIComponent ────────────────────────────────
function measureTree(component: UIComponent): void {
  console.log(`${component.getName()} → ${component.getRenderTime()} ms`);
}

measureTree(app);        // Panel[app] → 11 ms
measureTree(sidebar);    // Panel[sidebar] → 5 ms

console.log(app.render());
// <div class="panel" id="app">
//   <div class="panel" id="sidebar">...
//   <div class="panel" id="content">...
//   <button>Logout</button>
// </div>
